mkdir -p "app/api/v3/webhooks/[webhookId]/duplicate" app/api/v3/webhooks/lib && 
cat > app/api/v3/webhooks/serializers.ts <<'EOF'
import type { Webhook } from "@formbricks/database/prisma";

export type TV3Webhook = {
  id: string;
  name: string | null;
  url: string;
  source: Webhook["source"];
  triggers: Webhook["triggers"];
  /** Empty means every survey in the workspace, present and future. */
  surveyIds: string[];
  workspaceId: string;
  /** The shared secret recipients use to verify the HMAC signature of a delivery. */
  secret: string | null;
  createdAt: string;
  updatedAt: string;
};

export const serializeV3Webhook = (webhook: Webhook): TV3Webhook => ({
  id: webhook.id,
  name: webhook.name,
  url: webhook.url,
  source: webhook.source,
  triggers: webhook.triggers,
  surveyIds: webhook.surveyIds,
  workspaceId: webhook.workspaceId,
  secret: webhook.secret,
  createdAt: webhook.createdAt.toISOString(),
  updatedAt: webhook.updatedAt.toISOString(),
});
EOF
cat > app/api/v3/webhooks/lib/schemas.ts <<'EOF'
import { z } from "zod";

export const ZV3WebhookIdParams = z.object({ webhookId: z.cuid2() }).strict();

export const ZV3WebhookListQuery = z.object({ workspaceId: z.cuid2() }).strict();

export type TV3WebhookIdParams = z.infer<typeof ZV3WebhookIdParams>;
export type TV3WebhookListQuery = z.infer<typeof ZV3WebhookListQuery>;
EOF
cat > app/api/v3/webhooks/lib/operations.ts <<'EOF'
import "server-only";
import { InvalidInputError } from "@formbricks/types/errors";
import { requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import {
  createdResponse,
  problemForbidden,
  problemUnprocessableContent,
  successResponse,
} from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { assertNewlyAttachedSurveysWorkspaceVisible } from "@/lib/survey/visibility/outbound";
import { getWebhookWithSecret } from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { createWebhook, getWebhooks } from "@/modules/integrations/webhooks/lib/webhook";
import { serializeV3Webhook } from "../serializers";

type TBaseParams = {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
};

export const COPY_NAME_PREFIX = "Copy of";

/** "Copy of" plus the original name; a webhook with no name is labelled by its URL, as the table does. */
export const getDuplicateWebhookName = (original: { name: string | null; url: string }): string =>
  `${COPY_NAME_PREFIX} ${original.name || original.url}`;

export async function listV3Webhooks(params: TBaseParams & { workspaceId: string }): Promise<Response> {
  const { authentication, workspaceId, requestId, instance } = params;

  const access = await requireV3WorkspaceAccess(authentication, workspaceId, "read", requestId, instance);
  if (access instanceof Response) return access;

  const webhooks = await getWebhooks(access.workspaceId);

  return successResponse(webhooks.map(serializeV3Webhook), { requestId });
}

/**
 * The workspace is resolved from the webhook itself, never from the request, so a caller cannot pair
 * someone else's webhook id with a workspace they happen to have access to. An unknown webhook answers
 * 403, not 404, so webhook ids cannot be probed across the instance.
 */
export async function duplicateV3Webhook(
  params: TBaseParams & { webhookId: string; auditLog?: TV3AuditLog }
): Promise<Response> {
  const { authentication, webhookId, auditLog, requestId, instance } = params;

  const original = await getWebhookWithSecret(webhookId);
  if (!original.ok) {
    return problemForbidden(requestId, "You are not authorized to access this resource", instance);
  }

  const access = await requireV3WorkspaceAccess(
    authentication,
    original.data.workspaceId,
    "readWrite",
    requestId,
    instance
  );
  if (access instanceof Response) return access;

  // The copy attaches every survey the original has, so the same attach-time visibility guard as a create applies.
  await assertNewlyAttachedSurveysWorkspaceVisible(original.data.surveyIds);

  if (auditLog) {
    auditLog.organizationId = access.organizationId;
  }

  try {
    // No secret is passed, so `createWebhook` generates a fresh one for the copy.
    const copy = await createWebhook(access.workspaceId, {
      name: getDuplicateWebhookName(original.data),
      url: original.data.url,
      source: "user",
      triggers: original.data.triggers,
      surveyIds: original.data.surveyIds,
    });

    if (auditLog) {
      auditLog.targetId = copy.id;
      auditLog.newObject = { ...copy, secret: undefined };
    }

    return createdResponse(serializeV3Webhook(copy), {
      location: `/api/v3/webhooks?workspaceId=${access.workspaceId}`,
      requestId,
    });
  } catch (error) {
    // The original's URL no longer passes validation (for example, the instance now forbids internal URLs).
    if (error instanceof InvalidInputError) {
      return problemUnprocessableContent(requestId, "Unable to duplicate webhook", {
        instance,
        invalid_params: [{ name: "url", reason: error.message }],
      });
    }
    throw error;
  }
}
EOF
cat > app/api/v3/webhooks/route.ts <<'EOF'
/**
 * GET /api/v3/webhooks — list a workspace's webhooks, newest first.
 *
 * Session-only, like `/api/v3/tags`: it backs the webhooks settings screen, which already showed these
 * rows (secret included) to anyone who can read the workspace.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { listV3Webhooks } from "./lib/operations";
import { ZV3WebhookListQuery } from "./lib/schemas";

export const GET = withV3ApiWrapper({
  auth: "session",
  schemas: { query: ZV3WebhookListQuery },
  handler: async ({ authentication, parsedInput, requestId, instance }) =>
    listV3Webhooks({
      authentication,
      workspaceId: parsedInput.query.workspaceId,
      requestId,
      instance,
    }),
});
EOF
cat > "app/api/v3/webhooks/[webhookId]/duplicate/route.ts" <<'EOF'
/**
 * POST /api/v3/webhooks/{webhookId}/duplicate — create a webhook with the same URL, triggers and surveys,
 * named "Copy of <original name>", with a signing secret of its own.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { duplicateV3Webhook } from "../../lib/operations";
import { ZV3WebhookIdParams } from "../../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "session",
  action: "created",
  targetType: "webhook",
  schemas: { params: ZV3WebhookIdParams },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    duplicateV3Webhook({
      authentication,
      webhookId: parsedInput.params.webhookId,
      auditLog,
      requestId,
      instance,
    }),
});
EOF
sed -n 1,60p modules/api/v2/management/webhooks/\[webhookId\]/lib/webhook.ts; grep -n "targetId\|newObject" app/api/v3/lib/types.ts; sed -n 296,312p app/api/v3/lib/response.ts
